pub fn grammar_tokens_fold_list_targets(remaining: i64, node: Rc<Node>) -> Rc<Outcome<Rc<Vec<Rc<Node>>>>> {
    grammar_tokens_fold_list_targets_into(remaining, node, Rc::new(vec![]))
}

pub fn grammar_tokens_fold_list_targets_into(mut __tco_loop_remaining: i64, mut __tco_loop_node: Rc<Node>, mut __tco_loop_acc: Rc<Vec<Rc<Node>>>) -> Rc<Outcome<Rc<Vec<Rc<Node>>>>> {
    { loop {
        #[allow(unused_mut)]
        let mut remaining = __tco_loop_remaining;
        #[allow(unused_mut)]
        let mut node = __tco_loop_node;
        #[allow(unused_mut)]
        let mut acc = __tco_loop_acc;
        if (remaining.clone() <= 0) {
            break crate::v2_std_diagnostic::outcome_rejected(translate_grammar_inverse_not_realized_diagnostic(node.clone()));
} else {
            match (*node.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => { if crate::std_algebra::is_empty(node.children.clone()) {
                break Rc::new(Outcome::Accepted {
    value: acc.clone(),
    diagnostics: Box::new(std::option::Option::None),
});
} else {
                match (*conj_named_child(node.clone(), "fold_list_node_head".to_string())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => { break Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}); },
    Outcome::Accepted { value: head, .. } => { match (*conj_named_child(node.clone(), "fold_list_node_tail".to_string())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => { break Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}); },
    Outcome::Accepted { value: tail, .. } => { {
                    let __tco_0 = v1_rt::int_sub(remaining, 1);
let __tco_1 = tail.clone();
let __tco_2 = crate::std_algebra::list_snoc_item(acc, head.clone());
__tco_loop_remaining = __tco_0;
__tco_loop_node = __tco_1;
__tco_loop_acc = __tco_2;
continue;
} },
} },
}
} },
    Connective::Atom { identity: _, .. } => { break crate::v2_std_diagnostic::outcome_rejected(translate_grammar_inverse_not_realized_diagnostic(node.clone())); },
    Connective::Disj => { break crate::v2_std_diagnostic::outcome_rejected(translate_grammar_inverse_not_realized_diagnostic(node.clone())); },
    Connective::Arrow => { break crate::v2_std_diagnostic::outcome_rejected(translate_grammar_inverse_not_realized_diagnostic(node.clone())); },
    Connective::Instantiation => { break crate::v2_std_diagnostic::outcome_rejected(translate_grammar_inverse_not_realized_diagnostic(node.clone())); },
} },
    NodeKind::ComputationNode { behavior: _, .. } => { break crate::v2_std_diagnostic::outcome_rejected(translate_grammar_inverse_not_realized_diagnostic(node.clone())); },
}
}
} }
}

