pub fn translate_project_transform_surface_or_callable_in_arrow_scope(arrow: Rc<Node>, body: Rc<Node>, operator_child: Rc<Node>, target: Rc<TargetModel>) -> Rc<Outcome<Rc<TargetValueExpression>>> {
    match (*operator_child.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: op_sym, .. } => match (*crate::v2_extdeps_languages_dag::dag_surface_operator_canonicalization_member(op_sym.clone())).clone() {
    Outcome::Accepted { value: canonical_op, .. } => crate::v2_std_compilers_target_model::target_project_transform_primitive_apply_in_arrow_scope(arrow.clone(), body.clone(), canonical_op.clone(), target.clone()),
    Outcome::Rejected { diagnostics: _, .. } => crate::v2_std_compilers_target_model::target_project_transform_callable_apply_in_arrow_scope(arrow.clone(), body.clone(), target.clone(), crate::v2_extdeps_languages_dag::dag_value_expression_projection().bool_literal_form.clone(), |a, b, t| translate_project_transform_in_arrow_scope(a, b, t)),
},
    Connective::Conj => crate::v2_std_diagnostic::outcome_rejected(crate::v2_std_compilers_target_model::target_value_expr_diagnostic("target_value_expr_reason_transform_shape_invalid".to_string(), operator_child.clone())),
    Connective::Disj => crate::v2_std_diagnostic::outcome_rejected(crate::v2_std_compilers_target_model::target_value_expr_diagnostic("target_value_expr_reason_transform_shape_invalid".to_string(), operator_child.clone())),
    Connective::Arrow => crate::v2_std_diagnostic::outcome_rejected(crate::v2_std_compilers_target_model::target_value_expr_diagnostic("target_value_expr_reason_transform_shape_invalid".to_string(), operator_child.clone())),
    Connective::Instantiation => crate::v2_std_diagnostic::outcome_rejected(crate::v2_std_compilers_target_model::target_value_expr_diagnostic("target_value_expr_reason_transform_shape_invalid".to_string(), operator_child.clone())),
} },
    NodeKind::ComputationNode { behavior: _, .. } => crate::v2_std_diagnostic::outcome_rejected(crate::v2_std_compilers_target_model::target_value_expr_diagnostic("target_value_expr_reason_transform_shape_invalid".to_string(), operator_child.clone())),
}
}

pub fn translate_project_transform_in_arrow_scope(arrow: Rc<Node>, body: Rc<Node>, target: Rc<TargetModel>) -> Rc<Outcome<Rc<TargetValueExpression>>> {
    crate::v2_std_diagnostic::bind_outcome(crate::v2_std_compilers_target_model::target_transform_operator_child(body.clone()), |operator_child| match (*crate::v2_std_compilers_target_model::canonical_operation_from_wire_node(operator_child.clone())).clone() {
    Outcome::Accepted { value: canonical_op, .. } => crate::v2_std_compilers_target_model::target_project_transform_primitive_apply_in_arrow_scope(arrow.clone(), body.clone(), canonical_op.clone(), target.clone()),
    Outcome::Rejected { diagnostics: _, .. } => translate_project_transform_surface_or_callable_in_arrow_scope(arrow.clone(), body.clone(), operator_child.clone(), target.clone()),
})
}

