pub fn nullary_coproduct_arm_binding_spelling(body: Rc<Node>) -> Option<std::string::String> {
    match crate::v2_std_qualified_name::declaration_reference_path_optional(body) {
    std::option::Option::None => std::option::Option::None,
    Some(path) => match crate::v2_std_qualified_name::qualified_name_last_segment(path.clone()) {
    std::option::Option::None => std::option::Option::None,
    Some(leaf) => match crate::v2_std_qualified_name::qualified_name_last_segment(crate::v2_std_qualified_name::qualified_name_init(path.clone())) {
    std::option::Option::None => Some(leaf.clone()),
    Some(parent) => Some(v1_rt::symbol_intern_lexeme(v1_rt::concat(v1_rt::symbol_lexeme(parent.clone()), v1_rt::concat("::".to_string(), v1_rt::symbol_lexeme(leaf.clone()))))),
},
},
}
}

